-- deprecated: False
-- sha256: 23fdbb06b417e787cd17d03684d380e89f2f646814d124d703533675d079ed9e
CREATE TEMPORARY VIEW imp_click_${grass_region_without_quote} AS
select
     item_id
    ,case
        when ${grass_region} = 'ID' and array_contains(exp_group_ids,627728) then 'T1'
        when ${grass_region} = 'VN' and array_contains(exp_group_ids,640343) then 'T1'
        when ${grass_region} = 'PH' and array_contains(exp_group_ids,655654) then 'T1'
        when ${grass_region} = 'TH' and array_contains(exp_group_ids,655641) then 'T1'
        when ${grass_region} = 'MY' and array_contains(exp_group_ids,662593) then 'T1'
        when array_contains(exp_group_ids,378802) then 'C1'
        else 'OTHER'
     end as exp_tag -- 使用上报数据，和实时进行对齐；同时也为了解决时区问题
    ,sum(if(operation = 'impression',operation_cnt,0))  AS imp_cnt
    ,sum(if(operation = 'click' ,operation_cnt,0)) AS click_cnt
    ,sum(if(operation = 'order',operation_cnt,0)) AS order_cnt
FROM srdi_mart.dwd_sr_data_warehouse_platform
WHERE grass_region IN (${grass_region}) and regional_date = ${local_date} and operation in ('impression','click','order')
and (is_ads = false or is_ads is null) -- 只要organic的，不要广告
and item_id > 0
and (--只要推荐场景的
       (reporting_business_line = 'Rcmd' and reporting_module = 'User Scenario' and reporting_object = 'you may also like')
    or (reporting_business_line = 'Homepage' and reporting_module = 'Daily Discover')
    or (reporting_business_line = 'Rcmd' and reporting_module = 'User Scenario' and reporting_object = 'post purchase')
)
and (-- 限定和实时一样的卡片类型
       target_type = 'item'
    or (page_type = 'home' and page_section[0] = 'daily_discover' and target_type in ('item_feed_card','item_mix_feed_card','repurchase_mix_feed_card'))
)
group by
     item_id
    ,exp_group_ids
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_ni_boost_offline_common_1d PARTITION (grass_region = ${grass_region}, regional_date = ${local_date})
SELECT
     exp_tag
    ,item_id
    ,sum(imp_cnt)   as imp_cnt
    ,sum(click_cnt) as click_cnt
    ,sum(order_cnt) as order_cnt
FROM imp_click_${grass_region_without_quote}
group by exp_tag,item_id
